    "note_pedagogique": "Appelée « la sourate des bienfaits » tant elle énumère les grâces divines. Elle culmine sur l'abeille (naḥl) inspirée de bâtir ses ruches et de produire un miel « où se trouve une guérison pour les hommes ». Elle contient le célèbre verset de l'équité (v.90), lu à la fin de chaque prêche du vendredi, et se clôt sur l'appel à la sagesse et à la belle exhortation.",
