      "ar": "وَإِذَا بَدَّلْنَا ءَايَةً مَّكَانَ ءَايَةٍ وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُواْ إِنَّمَا أَنتَ مُفْتَرٍ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ",
      "translit": "Waʾidhā baddalnā āyatan makāna āyatin wallāhu aʿlamu bimā yunazzilu qālū innamā anta muftari bal aktharuhum lā yaʿlamūn",
