      "translit": "Idʿu ilā sabīli rabbika bil-ḥikmati wal-mawʿiẓati l-ḥasanati wajādilhum billatī hiya aḥsanu inna rabbaka huwa aʿlamu biman ḍalla ʿan sabīlihī wahuwa aʿlamu bil-muhtadīn",
